#include <array>
#include <cstddef>
#include <iostream>
#include <string_view>

class UndoPosition {
public:
    std::string_view set(int next) {
        if (next < 0 || next > 9) return "invalid";
        if (next == position_) return "unchanged";
        if (used_ == before_.size()) return "history full";

        before_[used_] = position_;
        ++used_;
        position_ = next;
        return "changed";
    }

    std::string_view undo() {
        if (used_ == 0) return "empty";
        --used_;
        position_ = before_[used_];
        return "undone";
    }

    int position() const { return position_; }
    std::size_t depth() const { return used_; }

private:
    int position_ = 2;
    std::array<int, 3> before_{};
    std::size_t used_ = 0;
};

void report(std::string_view request, std::string_view result,
            const UndoPosition& editor) {
    std::cout << request << ": " << result
              << ", position=" << editor.position()
              << ", depth=" << editor.depth() << '\n';
}

int main() {
    UndoPosition editor;
    report("undo", editor.undo(), editor);
    report("set(5)", editor.set(5), editor);
    report("set(5)", editor.set(5), editor);
    report("set(11)", editor.set(11), editor);
    report("set(1)", editor.set(1), editor);
    report("set(8)", editor.set(8), editor);
    report("set(8)", editor.set(8), editor);
    report("set(6)", editor.set(6), editor);
    report("undo", editor.undo(), editor);
    report("set(4)", editor.set(4), editor);
    report("undo", editor.undo(), editor);
    report("undo", editor.undo(), editor);
    report("undo", editor.undo(), editor);
    report("undo", editor.undo(), editor);
}
